import numpy as np
import pandas as pd

def model(regime, n, seed):
    rng = np.random.default_rng(seed)
    t_grid = list(regime.context.get("t_grid", ()))
    rows = []
    for i in range(n):
        ys = rng.normal(0, 1, size=len(t_grid))
        ys = ys - ys.mean() if len(ys) else ys
        for t, y in zip(t_grid, ys):
            rows.append((i, float(t), float(y)))
    return pd.DataFrame(rows, columns=["unit_id", "t", "y"])

